import numpy as np
import biotite.structure.io.pdbx as pdbx

one_model = {
    'group_PDB': ['ATOM'] * 4,
    'id': [1, 2, 3, 4],
    'type_symbol': ['C', 'C', 'N', 'N'],
    'label_atom_id': ['C', 'C', 'N', 'N'],
    'label_alt_id': ['A', 'B', 'A', 'B'],
    'label_comp_id': ['CYS'] * 4,
    'label_asym_id': ['A'] * 4,
    'label_seq_id': [1, 1, 2, 2],
    'pdbx_PDB_ins_code': ['?'] * 4,
    'Cartn_x': [0.0, 0.1, 1.0, 1.1],
    'Cartn_y': [0.0] * 4,
    'Cartn_z': [0.0] * 4,
    'occupancy': [0.25, 0.75, 0.25, 0.75],
    'auth_seq_id': [1, 1, 2, 2],
    'auth_comp_id': ['CYS'] * 4,
    'auth_asym_id': ['A'] * 4,
    'auth_atom_id': ['C', 'C', 'N', 'N'],
    'pdbx_PDB_model_num': [1] * 4,
}
site_data = {}
for key, values in one_model.items():
    if key == 'id':
        site_data[key] = values + [v + 4 for v in values]
    elif key == 'Cartn_x':
        site_data[key] = values + [v + 10 for v in values]
    elif key == 'pdbx_PDB_model_num':
        site_data[key] = values + [2] * 4
    else:
        site_data[key] = values + values
bond_data = {
    'comp_id': ['DUM'], 'atom_id_1': ['X'], 'atom_id_2': ['Y'],
    'value_order': ['SING'], 'pdbx_aromatic_flag': ['N'],
}
representations = [
    pdbx.CIFBlock({
        'atom_site': pdbx.CIFCategory(site_data),
        'chem_comp_bond': pdbx.CIFCategory(bond_data),
    }),
    pdbx.CIFFile({'test': pdbx.CIFBlock({
        'atom_site': pdbx.CIFCategory(site_data),
        'chem_comp_bond': pdbx.CIFCategory(bond_data),
    })}),
    pdbx.BinaryCIFBlock({
        'atom_site': pdbx.BinaryCIFCategory(site_data),
        'chem_comp_bond': pdbx.BinaryCIFCategory(bond_data),
    }),
    pdbx.BinaryCIFFile({'test': pdbx.BinaryCIFBlock({
        'atom_site': pdbx.BinaryCIFCategory(site_data),
        'chem_comp_bond': pdbx.BinaryCIFCategory(bond_data),
    })}),
]
for component in representations:
    for model in (1, None):
        for mode, expected_x in [('first', [0.0, 1.0]), ('occupancy', [0.1, 1.1])]:
            atoms = pdbx.get_structure(
                component, model=model, altloc=mode, include_bonds=True
            )
            assert atoms.array_length() == 2
            assert atoms.bonds.get_atom_count() == 2
            np.testing.assert_array_equal(atoms.bonds.as_array()[:, :2], [[0, 1]])
            np.testing.assert_allclose(atoms.coord[0, :, 0] if model is None else atoms.coord[:, 0], expected_x)
    all_atoms = pdbx.get_structure(
        component, model=1, altloc='all', include_bonds=True
    )
    assert all_atoms.array_length() == 4
    assert all_atoms.altloc_id.tolist() == ['A', 'B', 'A', 'B']
    assert all_atoms.bonds.get_atom_count() == 4
    print(type(component).__name__, 'ok')
